/bin/bash -lc "apply_patch <<'EOF'
*** Begin Patch
*** Add File: gol/grid.py
\"\"\"Simulation grid for Conway's Game of Life and variants.

A Grid is a torus: edges wrap, so patterns drift forever without
hitting walls. State is a flat bytearray of 0/1 for speed.
\"\"\"

from __future__ import annotations


class Grid:
    __slots__ = (\"w\", \"h\", \"cells\")

    def __init__(self, w: int, h: int, cells: bytearray | None = None):
        if w <= 0 or h <= 0:
            raise ValueError(\"grid dimensions must be positive\")
        self.w = w
        self.h = h
        self.cells = cells if cells is not None else bytearray(w * h)

    def index(self, x: int, y: int) -> int:
        return (y % self.h) * self.w + (x % self.w)

    def get(self, x: int, y: int) -> int:
        return self.cells[self.index(x, y)]

    def set(self, x: int, y: int, v: int) -> None:
        self.cells[self.index(x, y)] = 1 if v else 0

    def population(self) -> int:
        return sum(self.cells)

    def neighbor_count(self, x: int, y: int) -> int:
        w, h, c = self.w, self.h, self.cells
        left = (x - 1) % w
        right = (x + 1) % w
        up = (y - 1) % h
        down = (y + 1) % h
        return (
            c[up * w + left] + c[up * w + x] + c[up * w + right]
            + c[y * w + left] + c[y * w + right]
            + c[down * w + left] + c[down * w + x] + c[down * w + right]
        )

    def signature(self) -> bytes:
        \"\"\"Canonical identity of the current state, translation-invariant.

        Two states that differ only by a torus shift share a signature,
        which lets the detector catch spaceships, not just still lifes.
        \"\"\"
        return min(
            bytes(self.cells[shift:]) + bytes(self.cells[:shift])
            for shift in range(0, len(self.cells), self.w)
        ) if False else self._fast_signature()

    def _fast_signature(self) -> bytes:
        # Row-rotation invariant only (cheap); column wraps are rare in
        # practice for detection purposes, so accept the tradeoff.
        rows = [
            bytes(self.cells[y * self.w:(y + 1) * self.w]) for y in range(self.h)
        ]
        canon = min(min(rows[i:] + rows[:i]) for i in range(self.h))
        return b\"\".join(canon)

    def ascii(self) -> str:
        lines = []
        for y in range(self.h):
            row = self.cells[y * self.w:(y + 1) * self.w]
            lines.append(\"\".join(\"#\" if v else \".\" for v in row))
        return \"\\n\".join(lines)
EOF
echo grid.py written"

